css:
.switch-button {
  display: flex;
  align-items: center;
  justify-content: center;
  margin: auto;
  height: 55px;
}

/* OUTER TRACK  */
.switch-button .switch-outer {
  height: 100%;
  width: 115px;

  /* subtle surface gradient */
  background: linear-gradient(180deg, #ffffff 0%, #f3f4f6 100%);

  border-radius: 165px;

  /* crisp rim + soft inner */
  border: 1px solid rgba(0, 0, 0, 0.1);

  box-shadow:
    /* soft outer shadow */
    0px 10px 22px rgba(0, 0, 0, 0.1),
    0px 2px 6px rgba(0, 0, 0, 0.1),
    /* inner highlight + inner shade */ inset 0px 2px 2px
      rgba(255, 255, 255, 0.95),
    inset 0px -5px 10px rgba(0, 0, 0, 0.06);

  padding: 6px;
  box-sizing: border-box;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;

  /* helps with absolute input */
  position: relative;
}

.switch-button .switch-outer input[type="checkbox"] {
  opacity: 0;
  appearance: none;
  position: absolute;
}

/* BUTTON ROW */
.switch-button .switch-outer .button {
  width: 100%;
  height: 100%;
  display: flex;
  position: relative;
  justify-content: space-between;
  align-items: center;
}

/* KNOB */
.switch-button .switch-outer .button-toggle {
  height: 42px;
  width: 42px;
  border-radius: 50%;

  background: radial-gradient(
    circle at 30% 25%,
    #ffffff 0%,
    #f2f3f5 45%,
    #e3e5e8 100%
  );

  /* rim for definition */
  border: 1px solid rgba(0, 0, 0, 0.08);

  box-shadow:
    /* top highlight */
    inset 0px 2px 3px rgba(255, 255, 255, 0.95),
    /* inner shade */ inset 0px -6px 10px rgba(0, 0, 0, 0.08),
    /* lift */ 0px 10px 18px rgba(0, 0, 0, 0.16),
    0px 2px 5px rgba(0, 0, 0, 0.12);

  position: relative;
  z-index: 2;
  transition: left 0.28s ease-in-out;
  left: 0;
}

/* CHECKED STATE — knob slide */
.switch-button
  .switch-outer
  input[type="checkbox"]:checked
  + .button
  .button-toggle {
  left: 58%;
}

/* INDICATOR RING */
.switch-button .switch-outer .button-indicator {
  height: 24px;
  width: 24px;
  border-radius: 50%;

  /* start as “off” red */
  border: 3px solid #ff5b61;

  background: rgba(255, 255, 255, 0.9);

  box-shadow:
    0px 1px 2px rgba(0, 0, 0, 0.12),
    inset 0px 1px 1px rgba(255, 255, 255, 0.7);

  position: relative;
  right: 10px;
}

.switch-button
  .switch-outer
  input[type="checkbox"]:checked
  + .button
  .button-indicator {
  animation: indicator 0.9s forwards;
}

@keyframes indicator {
  0% {
    opacity: 1;
  }
  30% {
    opacity: 0;
  }
  100% {
    opacity: 1;
    border: 3px solid #35c759;
    left: -68%;
  }
}
